function bandingkanApi(lama, baru) {
  const petaLama = new Map(lama.map((x) => [x.nama, x.params.join(",")]));
  const petaBaru = new Map(baru.map((x) => [x.nama, x.params.join(",")]));
  const dihapus = [...petaLama.keys()].filter((n) => !petaBaru.has(n)).sort();
  const ditambah = [...petaBaru.keys()].filter((n) => !petaLama.has(n)).sort();
  const berubah = [...petaLama.keys()]
    .filter((n) => petaBaru.has(n) && petaBaru.get(n) !== petaLama.get(n))
    .sort();
  return { dihapus, ditambah, berubah };
}

