function cekNamaPaket(nama) {
  if (nama.length === 0) return ["kosong"];
  const salah = [];
  if (nama.length > 214) salah.push("terlalu-panjang");
  if (nama !== nama.toLowerCase()) salah.push("huruf-besar");
  if (nama.startsWith(".") || nama.startsWith("_")) salah.push("awalan-terlarang");
  const aman = /^[a-z0-9._~-]+$/i;
  const scope = nama.match(/^@([^/]+)\/([^/]+)$/);
  const bagian = scope ? [scope[1], scope[2]] : [nama];
  if (!bagian.every((b) => aman.test(b))) salah.push("karakter-tidak-aman");
  if (_modulInti.includes(nama)) salah.push("modul-inti");
  return salah;
}

function isiTarball(semuaBerkas, pkg) {
  const diabaikan = (p) => {
    const bagian = p.split("/");
    return bagian.some((b) => b === "node_modules" || b === ".git") ||
      [".npmrc", "package-lock.json"].includes(bagian[bagian.length - 1]);
  };
  const main = (pkg.main || "").replace(/^\.\//, "");
  const selaluIkut = (p) =>
    p === "package.json" || p === main ||
    (!p.includes("/") && /^(readme|licen[cs]e)/i.test(p));
  const cocokPola = (p, pola) => {
    pola = pola.replace(/^\.\//, "").replace(/\/$/, "");
    if (pola.startsWith("*.")) return !p.includes("/") && p.endsWith(pola.slice(1));
    return p === pola || p.startsWith(pola + "/");
  };
  return semuaBerkas
    .filter((p) => !diabaikan(p))
    .filter((p) => !pkg.files || selaluIkut(p) || pkg.files.some((f) => cocokPola(p, f)))
    .sort();
}

