function bandingkanVersi(a, b) {
  const x = _parse(a), y = _parse(b);
  for (let i = 0; i < 3; i++) {
    if (x.inti[i] !== y.inti[i]) return x.inti[i] < y.inti[i] ? -1 : 1;
  }
  if (!x.pre.length || !y.pre.length) {
    if (x.pre.length === y.pre.length) return 0;
    return x.pre.length ? -1 : 1;
  }
  for (let i = 0; i < Math.max(x.pre.length, y.pre.length); i++) {
    const p = x.pre[i], q = y.pre[i];
    if (p === undefined) return -1;
    if (q === undefined) return 1;
    if (p === q) continue;
    if (typeof p !== typeof q) return typeof p === "number" ? -1 : 1;
    return p < q ? -1 : 1;
  }
  return 0;
}

function cocokRentang(versi, rentang) {
  const op = rentang[0] === "^" || rentang[0] === "~" ? rentang[0] : "";
  const dasar = rentang.slice(op.length);
  if (!op) return bandingkanVersi(versi, dasar) === 0;
  const v = _parse(versi), d = _parse(dasar);
  if (v.pre.length && !(d.pre.length && v.inti.join(".") === d.inti.join("."))) return false;
  const [mj, mn, pt] = d.inti;
  let atas;
  if (op === "~") atas = `${mj}.${mn + 1}.0`;
  else if (mj > 0) atas = `${mj + 1}.0.0`;
  else if (mn > 0) atas = `0.${mn + 1}.0`;
  else atas = `0.0.${pt + 1}`;
  return bandingkanVersi(versi, dasar) >= 0 && bandingkanVersi(versi, atas) < 0;
}

