// Pembantu latihan (tiruan sederhana, bukan node-semver).
// _parse("1.2.3-beta.1") -> { inti: [1, 2, 3], pre: ["beta", 1] }
function _parse(v) {
  const m = /^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?$/.exec(v);
  if (!m) throw new Error("versi tidak sah: " + v);
  const pre = m[4] ? m[4].split(".").map((x) => (/^\d+$/.test(x) ? Number(x) : x)) : [];
  return { inti: [Number(m[1]), Number(m[2]), Number(m[3])], pre };
}

