function resolveExports(pkg, subpath, kondisi) {
  let peta = pkg.exports;
  const tanpaSubpath = typeof peta === "string" || !Object.keys(peta).some((k) => k.startsWith("."));
  if (tanpaSubpath) peta = { ".": peta };

  const gagal = () => {
    const e = new Error(`Package subpath '${subpath}' is not defined by "exports"`);
    e.code = "ERR_PACKAGE_PATH_NOT_EXPORTED";
    return e;
  };

  const selesaikan = (target) => {
    if (typeof target === "string") return target;
    if (target === null || typeof target !== "object") return null;
    for (const kunci of Object.keys(target)) {
      if (kunci === "default" || kondisi.includes(kunci)) {
        const hasil = selesaikan(target[kunci]);
        if (hasil !== null) return hasil;
      }
    }
    return null;
  };

  if (!Object.hasOwn(peta, subpath)) throw gagal();
  const hasil = selesaikan(peta[subpath]);
  if (hasil === null) throw gagal();
  return hasil;
}

