solution.code:
function cekProperti(gen, sifat, n, seed = 42) {
  const acak = _acak(seed);
  const gagal = (x) => {
    try {
      return sifat(x) !== true;
    } catch {
      return true;
    }
  };
  for (let i = 0; i < n; i++) {
    const x = gen(acak);
    if (gagal(x)) return { ok: false, asli: x, contoh: shrink(x, gagal) };
  }
  return { ok: true };
}

function shrink(x, gagal) {
  let sekarang = x;
  while (true) {
    const kandidat = [0, Math.trunc(sekarang / 2), sekarang - Math.sign(sekarang)];
    const lebihKecil = kandidat.find((k) => k !== sekarang && gagal(k));
    if (lebihKecil === undefined) return sekarang;
    sekarang = lebihKecil;
  }
}

