// Tiruan kecil untuk latihan, bukan API fast-check.
// _acak(seed) mengembalikan fungsi yang memberi angka acak 0 <= x < 1, selalu sama untuk seed yang sama.
function _acak(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Generator bilangan bulat min..max (inklusif). gen(acak) -> angka.
function _bilBulat(min, max) {
  return (acak) => min + Math.floor(acak() * (max - min + 1));
}

// terbilang yang sengaja salah: 1000 sampai 1999 dieja "satu ribu ..." bukan "seribu ...".
function _terbilangSalah(n) {
  const s = ["", "satu", "dua", "tiga", "empat", "lima", "enam", "tujuh", "delapan", "sembilan", "sepuluh", "sebelas"];
  const tiga = (x) => {
    const r = Math.floor(x / 100), p = x % 100, out = [];
    if (r === 1) out.push("seratus"); else if (r > 1) out.push(s[r] + " ratus");
    if (p > 0 && p < 12) out.push(s[p]);
    else if (p >= 12 && p < 20) out.push(s[p - 10] + " belas");
    else if (p >= 20) out.push(s[Math.floor(p / 10)] + " puluh" + (p % 10 ? " " + s[p % 10] : ""));
    return out.join(" ");
  };
  if (n === 0) return "nol";
  if (n < 0) return "minus " + _terbilangSalah(-n);
  const ribu = Math.floor(n / 1000), sisa = n % 1000;
  const depan = ribu === 0 ? "" : tiga(ribu) + " ribu";
  return [depan, tiga(sisa)].filter(Boolean).join(" ");
}

let _panggilan = 0;
function _hitung(gen) {
  return (acak) => { _panggilan++; return gen(acak); };
}

