function lintPaket(pkg, berkas) {
  const masalah = [];
  if (!Array.isArray(pkg.files) || pkg.files.length === 0) {
    masalah.push({ aturan: "files-kosong", path: "files" });
  }

  function periksa(nilai, path, kunciInduk) {
    if (typeof nilai === "string") {
      if (!berkas.includes(nilai.replace(/^\.\//, ""))) {
        masalah.push({ aturan: "target-hilang", path });
      }
      if (pkg.type === "module" && kunciInduk === "types" && path.includes("> require >") && nilai.endsWith(".d.ts")) {
        masalah.push({ aturan: "masquerading-esm", path });
      }
      return;
    }
    const kunci = Object.keys(nilai);
    const objekKondisi = kunci.length > 0 && !kunci[0].startsWith(".");
    if (objekKondisi) {
      if (kunci.includes("types") && kunci[0] !== "types") {
        masalah.push({ aturan: "types-bukan-pertama", path });
      }
      if (kunci.includes("default") && kunci.at(-1) !== "default") {
        masalah.push({ aturan: "default-bukan-terakhir", path });
      }
    }
    for (const k of kunci) periksa(nilai[k], path + " > " + k, k);
  }

  if (pkg.exports !== undefined) periksa(pkg.exports, "exports", "");
  return masalah;
}

