solution.code:
function jenisCommit(pesan) {
  const baris = pesan.split("\n");
  const m = /^([a-z]+)(\([^)]*\))?(!)?: /.exec(baris[0]);
  if (!m) return null;
  if (m[3] === "!" || baris.some((b) => b.startsWith("BREAKING CHANGE:"))) return "major";
  if (m[1] === "feat") return "minor";
  if (m[1] === "fix") return "patch";
  return null;
}

function versiBerikutnya(versi, commits) {
  const [major, minor, patch] = versi.split(".").map(Number);
  const urutan = ["patch", "minor", "major"];
  let jenis = null;
  for (const c of commits) {
    const j = jenisCommit(c);
    if (j && (jenis === null || urutan.indexOf(j) > urutan.indexOf(jenis))) jenis = j;
  }
  if (jenis === null) return null;
  if (jenis === "major" && major === 0) jenis = "minor";
  if (jenis === "major") return `${major + 1}.0.0`;
  if (jenis === "minor") return `${major}.${minor + 1}.0`;
  return `${major}.${minor}.${patch + 1}`;
}

