solution.code:
function terbitkan(registry, pkg, opsi = {}) {
  const id = `${pkg.name}@${pkg.version}`;
  if (registry.pernah.includes(id)) return { ok: false, alasan: "versi-sudah-ada" };
  if (pkg.version.includes("-") && !opsi.tag) return { ok: false, alasan: "prerelease-butuh-tag" };
  const akses = opsi.access ?? pkg.publishConfig?.access;
  if (pkg.name.startsWith("@") && akses !== "public") return { ok: false, alasan: "scope-butuh-akses-publik" };

  if (!registry.paket[pkg.name]) registry.paket[pkg.name] = { versi: {}, distTags: {} };
  const tag = opsi.tag ?? "latest";
  registry.paket[pkg.name].versi[pkg.version] = pkg;
  registry.paket[pkg.name].distTags[tag] = pkg.version;
  registry.pernah.push(id);
  return { ok: true, tag };
}

