solution.code:
function jarakEdit(a, b) {
  let baris = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const baru = [i];
    for (let j = 1; j <= b.length; j++) {
      const ganti = baris[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1);
      baru.push(Math.min(baris[j] + 1, baru[j - 1] + 1, ganti));
    }
    baris = baru;
  }
  return baris[b.length];
}

function polos(nama) {
  return nama.replace(/[-_.]/g, "");
}

function curigaTyposquat(nama, populer) {
  return populer.filter((p) => p !== nama && (jarakEdit(nama, p) === 1 || polos(nama) === polos(p)));
}
